function weightedTotal(scores, weights) {
  let total = 0;
  for (let i = 0; i < scores.length; i++) total += scores[i] * weights[i];
  return total / 100;
}

function weightsAreValid(weights) {
  return weights.reduce((a, b) => a + b, 0) === 100;
}

function bestName(names, totals) {
  let best = 0;
  for (let i = 1; i < totals.length; i++) {
    if (totals[i] > totals[best]) best = i;
  }
  return names[best];
}

function topGap(totals) {
  const sorted = [...totals].sort((a, b) => b - a);
  return sorted[0] - sorted[1];
}

function allSame(winners) {
  return winners.every((w) => w === winners[0]);
}

function isThin(gap, best) {
  return gap * 10 < best;
}

function toHundred(weights) {
  const sum = weights.reduce((a, b) => a + b, 0);
  return weights.map((w) => Math.round((w * 100) / sum));
}

function weightedScore(scores, weights) {
  let total = 0;
  for (const criterion in weights) {
    total += scores[criterion] * weights[criterion];
  }
  return total / 100;
}

function rankNames(options, weights) {
  const total = (o) =>
    Object.keys(weights).reduce((sum, c) => sum + o.scores[c] * weights[c], 0);
  return options
    .map((o) => ({ name: o.name, total: total(o) }))
    .sort((a, b) => b.total - a.total)
    .map((o) => o.name);
}

function winnersByWeighting(options, weightSets) {
  return weightSets.map(({ label, weights }) => {
    let winner = null;
    let best = -Infinity;
    for (const o of options) {
      let total = 0;
      for (const c in weights) total += o.scores[c] * weights[c];
      if (total > best) {
        best = total;
        winner = o.name;
      }
    }
    return { label, winner };
  });
}

function firstFlip(options, weightSets) {
  const winnerOf = (weights) => {
    let winner = null;
    let best = -Infinity;
    for (const o of options) {
      let total = 0;
      for (const c in weights) total += o.scores[c] * weights[c];
      if (total > best) {
        best = total;
        winner = o.name;
      }
    }
    return winner;
  };
  const baseline = winnerOf(weightSets[0].weights);
  for (const set of weightSets) {
    if (winnerOf(set.weights) !== baseline) return set.label;
  }
  return null;
}
